<body>
<div class="wrap">
  <header>
    <h1>Szokáskövető</h1>
    <p class="sub">Jelöld be azokat a napokat, amelyiken teljesítetted a szokást. A sorozat azt mutatja, hány egymást követő nap ment egyben.</p>
  </header>

  <section class="stats" aria-label="Áttekintés">
    <div class="stat"><div class="num" id="sHab">0</div><div class="lbl">szokás</div></div>
    <div class="stat"><div class="num" id="sBest">0</div><div class="lbl">legjobb sorozat (nap)</div></div>
    <div class="stat"><div class="num" id="sWeek">0/35</div><div class="lbl">teljesített e héten</div></div>
  </section>

  <form class="add" id="addForm">
    <label class="sr" for="addInput">Új szokás neve</label>
    <input id="addInput" type="text" maxlength="40" placeholder="pl. 10 perc séta" autocomplete="off">
    <button id="addBtn" type="submit">Hozzáad</button>
  </form>

  <div id="empty" class="empty">
    <h2>Még nincs szokásod</h2>
    <p>Add hozzá az első szokásodat fent, és kezdd el jelölni a napokat.</p>
  </div>

  <div id="grid" class="grid"></div>
  <p class="sr" role="status" aria-live="polite" id="live"></p>
</div>

<script>
(function(){
  var KEY='habits-tracker-v1';
  var DOW=['H','K','Sze','Cs','P','Szo','V'];
  var DOW_FULL=['hétfő','kedd','szerda','csütörtök','péntek','szombat','vasárnap'];
  var todayIndex=(new Date().getDay()+6)%7;
  var state={habits:[]};
  var grid=document.getElementById('grid');
  var empty=document.getElementById('empty');
  var live=document.getElementById('live');
  var addInput=document.getElementById('addInput');
  var addBtn=document.getElementById('addBtn');
  var sHab=document.getElementById('sHab'),sBest=document.getElementById('sBest'),sWeek=document.getElementById('sWeek');
  var checkSVG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12l5 5L20 6"/></svg>';

  function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7);}
  function esc(s){return String(s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function currentStreak(h){var s=0,i=todayIndex;while(i>=0&&h.days[i]){s++;i--;}return s;}
  function bestStreak(h){var b=0,c=0,i;for(i=0;i<7;i++){if(h.days[i]){c++;if(c>b)b=c;}else c=0;}return b;}
  function announce(m){live.textContent=m;}

  function render(){
    var totalDone=0,maxBest=0,html='';
    state.habits.forEach(function(h){
      var cur=currentStreak(h),best=bestStreak(h),done=h.days.filter(Boolean).length;
      totalDone+=done; if(best>maxBest)maxBest=best;
      var cells='';
      for(var i=0;i<7;i++){
        var isDone=!!h.days[i];
        var aria='H: '+h.name+', '+DOW_FULL[i]+(isDone?', teljesítve':', még nem');
        cells+='<button type="button" class="day'+(isDone?' done':'')+(i===todayIndex?' today':'')+'" data-h="'+h.id+'" data-i="'+i+'" aria-pressed="'+(isDone?'true':'false')+'" aria-label="'+esc(aria)+'"><span class="dow">'+DOW[i]+'</span><span class="dot">'+checkSVG+'</span></button>';
      }
      html+='<div class="card"><div class="card-top"><span class="hab-name">'+esc(h.name)+'</span><span class="streak" title="Legjobb sorozat: '+best+' nap">&#128293; '+cur+' nap</span></div><div class="days">'+cells+'</div></div>';
    });
    grid.innerHTML=html;
    sHab.textContent=state.habits.length;
    sBest.textContent=maxBest;
    sWeek.textContent=totalDone+'/35';
    empty.style.display=state.habits.length?'none':'block';
    grid.style.display=state.habits.length?'grid':'none';
    addBtn.disabled=state.habits.length>=5;
    addInput.disabled=state.habits.length>=5;
    addBtn.textContent=state.habits.length>=5?'Teljes (5/5)':'Hozzáad';
    if(state.habits.length>=5)addInput.placeholder='Maximum 5 szokás';
  }

  function save(){
    if(window.alfy&&window.alfy.storage){
      try{window.alfy.storage.set(KEY,state);}catch(e){}
    }
  }
  function load(){
    if(window.alfy&&window.alfy.storage){
      try{
        var p=window.alfy.storage.get(KEY);
        if(p&&p.then){p.then(function(v){if(v&&v.habits)state={habits:v.habits};render();}).catch(function(){});}
        else if(p&&p.habits){state={habits:p.habits};render();}
      }catch(e){}
    }
  }

  grid.addEventListener('click',function(e){
    var b=e.target.closest('.day');
    if(!b)return;
    var h=state.habits.filter(function(x){return x.id===b.dataset.h;})[0];
    if(!h)return;
    var i=+b.dataset.i;
    h.days[i]=!h.days[i];
    save();
    render();
    announce(h.name+': '+DOW_FULL[i]+(h.days[i]?' bejelölve, teljesítve':' jelölés törölve'));
  });

  document.getElementById('addForm').addEventListener('submit',function(e){
    e.preventDefault();
    if(state.habits.length>=5){announce('Elérted a maximum 5 szokást.');return;}
    var name=addInput.value.trim();
    if(!name){addInput.focus();announce('Írd be a szokás nevét.');return;}
    state.habits.push({id:uid(),name:name,days:[false,false,false,false,false,false,false]});
    addInput.value='';
    save();
    render();
    announce('Hozzáadva: '+name);
    addInput.focus();
  });

  render();
  load();
})();
</script>
</body>
</html>
